        # Recursively call to_cuda on the value
        batch[key] = to_cuda(value, device, ignore_list)
    # Return the modified dictionary
    return batch

# If the input batch is not a tuple, list, or dictionary, assume it's a torch.Tensor
elif isinstance(batch, torch.Tensor):
    # Move the tensor to the specified CUDA device
    return batch.to(device)

# If the input batch is not a torch.Tensor, raise a TypeError
else:
    raise TypeError("Unsupported input type. Only tuples, lists, dictionaries, and torch.Tensor are supported.")

